CREATE TABLE schedule_lock (id INTEGER PRIMARY KEY CHECK (id=1));
INSERT INTO schedule_lock VALUES (1);
CREATE TABLE asset (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, location VARCHAR(120) NOT NULL);
CREATE TABLE technician (username VARCHAR(40) PRIMARY KEY, display_name VARCHAR(100) NOT NULL);
INSERT INTO technician VALUES ('technician','Alex Nguyen');
CREATE TABLE booking_batch (request_key VARCHAR(36) PRIMARY KEY, payload_hash VARCHAR(64) NOT NULL, actor VARCHAR(80) NOT NULL);
CREATE TABLE work_order (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 asset_id BIGINT NOT NULL REFERENCES asset(id), technician VARCHAR(40) NOT NULL REFERENCES technician(username),
 title VARCHAR(140) NOT NULL, starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL,
 status VARCHAR(20) NOT NULL CHECK (status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')),
 version BIGINT NOT NULL DEFAULT 0, batch_key VARCHAR(36) NOT NULL REFERENCES booking_batch(request_key), occurrence INTEGER NOT NULL,
 CHECK (ends_at > starts_at), UNIQUE(batch_key, occurrence));
CREATE INDEX ix_work_window ON work_order(starts_at, ends_at);
CREATE TABLE audit_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, work_id BIGINT NOT NULL REFERENCES work_order(id), actor VARCHAR(80) NOT NULL, action VARCHAR(30) NOT NULL, note VARCHAR(1000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
